(** 0RB1LD_0RC1LB_1RD0LB_1LA1RC *)
(** 0RB1LD_0RC1LB_1RD0LB_1LA1RC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LD_0RC1LB_1RD0LB_1LA1RC : TM := fun q s => match q, s with
