Lemma fireo_0RB1LD_1LA1RC_1RB0RC_0LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LD_1LA1RC_1RB0RC_0LD1RB = Some t ->
