Lemma geo_0RB1LD_1LC1RB_0RB1LD_1RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LD_1LC1RB_0RB1LD_1RA0LC) = lift (Cc (Pos.succ p)).
