(** ** The lap *)

Lemma lap_0RB1LD_1LC1RB_0RB1LD_1RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
