  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LD_1LC1RB_0RB1LD_1RA0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LD_1LC1RB_0RB1LD_1RA0LC B0_0RB1LD_1LC1RB_0RB1LD_1RA0LC B1_0RB1LD_1LC1RB_0RB1LD_1RA0LC 4 13 p j' [] []).
    + exact run_ovf_0RB1LD_1LC1RB_0RB1LD_1RA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LD_1LC1RB_0RB1LD_1RA0LC p j' E).
    + exact (geo_0RB1LD_1LC1RB_0RB1LD_1RA0LC p j' E).
    + lia.
Qed.

