Theorem qhtr_0RB1LD_1LC1RB_0RB1LD_1RA0LC : NonHalt tm_0RB1LD_1LC1RB_0RB1LD_1RA0LC /\ QHBoundTr 32779478 tm_0RB1LD_1LC1RB_0RB1LD_1RA0LC /\ QuasiHaltsTr tm_0RB1LD_1LC1RB_0RB1LD_1RA0LC.
