    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1RB_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1RB_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 1]).
