      with (l := [SWin 6]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RB_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 7; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1RB_1LA1LC_1RD0LC_0RD1LA
      with (l := [SWin 3]).
