Lemma fire_0RB1RB_1LC0LC_1RD1LA_0RD1LC : forall t, ~ In t pins_0RB1RB_1LC0LC_1RD1LA_0RD1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
