    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := [SWin 3; SWin 1]).
