    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := [SWin 3; SWin 2; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1RB_1LC0LC_1RD1LA_0RD1LC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
Qed.

