Definition tmw_0RB1RB_1LC0RC_1LA1LD_1RC0LD : TM := tm_wrap_trs tm_0RB1RB_1LC0RC_1LA1LD_1RC0LD pins_0RB1RB_1LC0RC_1LA1LD_1RC0LD.
