    apply (lap_of_run tm Cc true true cho_0RB1RB_1LC1LD_0RC1LA_1RC0LD B0_0RB1RB_1LC1LD_0RC1LA_1RC0LD B1_0RB1RB_1LC1LD_0RC1LA_1RC0LD 2 12 p j' [] []).
