  apply (fire_of_run_instr tm Cc true true l B0_0RB1RB_1LC1LD_0RC1LA_1RC0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RB_1LC1LD_0RC1LA_1RC0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1RB_1LC1LD_0RC1LA_1RC0LD : forall t, ~ In t pins_0RB1RB_1LC1LD_0RC1LA_1RC0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1RB_1LC1LD_0RC1LA_1RC0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1RB_1LC1LD_0RC1LA_1RC0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1RB_1LC1LD_0RC1LA_1RC0LD
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1RB_1LC1LD_0RC1LA_1RC0LD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
