    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := [SWin 5; SCycL 1 0; SWin 2; SRotR 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := [SWin 5; SCycL 1 0; SWin 2; SRotR 1; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1RB_1LC1LD_1RB0RA_1RC0LD
      with (l := [SWin 3]).
